static const double abs_resolution_mult = 10000.0;
static const double abs_resolution_range_mult = 10.0;

struct MotifWmHints
{
	unsigned long flags;
	unsigned long functions;
	unsigned long decorations;
	long input_mode;
	unsigned long status;
};

enum
{
	MWM_HINTS_FUNCTIONS = (1L << 0),
	MWM_HINTS_DECORATIONS = (1L << 1),

	MWM_FUNC_ALL = (1L << 0),
	MWM_FUNC_RESIZE = (1L << 1),
	MWM_FUNC_MOVE = (1L << 2),
	MWM_FUNC_MINIMIZE = (1L << 3),
	MWM_FUNC_MAXIMIZE = (1L << 4),
	MWM_FUNC_CLOSE = (1L << 5),

	MWM_DECOR_ALL = (1L << 0),
	MWM_DECOR_BORDER = (1L << 1),
	MWM_DECOR_RESIZEH = (1L << 2),
	MWM_DECOR_TITLE = (1L << 3),
	MWM_DECOR_MENU = (1L << 4),
	MWM_DECOR_MINIMIZE = (1L << 5),
	MWM_DECOR_MAXIMIZE = (1L << 6),
};

static String get_atom_name(Display* p_disp, Atom p_atom)
{
	char* name = XGetAtomName(p_disp, p_atom);
	ERR_FAIL_NULL_V_MSG(name, String(), "Atom is invalid.");
	String ret = String::utf8(name);
	XFree(name);
	return ret;
}

bool DisplayServerX11::has_feature(DisplayServerEnums::Feature p_feature) const
{
	switch (p_feature) {
#ifndef DISABLE_DEPRECATED
	case DisplayServerEnums::FEATURE_GLOBAL_MENU: {
		return NativeMenu::is_initialized() && NativeMenu::has_feature(NativeMenu::FEATURE_GLOBAL_MENU);
	} break;
#endif
	case DisplayServerEnums::FEATURE_SUBWINDOWS:
#ifdef TOUCH_ENABLED
	case DisplayServerEnums::FEATURE_TOUCHSCREEN:
#endif
	case DisplayServerEnums::FEATURE_MOUSE:
	case DisplayServerEnums::FEATURE_MOUSE_WARP:
	case DisplayServerEnums::FEATURE_CLIPBOARD:
	case DisplayServerEnums::FEATURE_CURSOR_SHAPE:
	case DisplayServerEnums::FEATURE_CUSTOM_CURSOR_SHAPE:
	case DisplayServerEnums::FEATURE_IME:
	case DisplayServerEnums::FEATURE_WINDOW_TRANSPARENCY:
	// case DisplayServerEnums::FEATURE_HIDPI:
	case DisplayServerEnums::FEATURE_ICON:
	// case DisplayServerEnums::FEATURE_NATIVE_ICON:
	case DisplayServerEnums::FEATURE_SWAP_BUFFERS:
#ifdef DBUS_ENABLED
	case DisplayServerEnums::FEATURE_KEEP_SCREEN_ON:
#endif
	case DisplayServerEnums::FEATURE_CLIPBOARD_PRIMARY:
	case DisplayServerEnums::FEATURE_WINDOW_EMBEDDING:
	case DisplayServerEnums::FEATURE_WINDOW_DRAG: {
		return true;
	} break;

	// case DisplayServerEnums::FEATURE_NATIVE_DIALOG:
	// case DisplayServerEnums::FEATURE_NATIVE_DIALOG_INPUT:
#ifdef DBUS_ENABLED
	case DisplayServerEnums::FEATURE_NATIVE_DIALOG_FILE:
	case DisplayServerEnums::FEATURE_NATIVE_DIALOG_FILE_EXTRA:
	case DisplayServerEnums::FEATURE_NATIVE_DIALOG_FILE_MIME: {
		return (portal_desktop && portal_desktop->is_supported() &&
				portal_desktop->is_file_chooser_supported());
	} break;
	case DisplayServerEnums::FEATURE_NATIVE_COLOR_PICKER: {
		return (portal_desktop && portal_desktop->is_supported() &&
				portal_desktop->is_screenshot_supported());
	} break;
#endif
	case DisplayServerEnums::FEATURE_SCREEN_CAPTURE: {
		return !xwayland;
	} break;

#ifdef SPEECHD_ENABLED
	case DisplayServerEnums::FEATURE_TEXT_TO_SPEECH: {
		return true;
	} break;
#endif

	case DisplayServerEnums::FEATURE_ACCESSIBILITY_SCREEN_READER: {
		return AccessibilityServer::is_supported();
	} break;

	default: {
		return false;
	}
	}
}

String DisplayServerX11::get_name() const { return "X11"; }

void DisplayServerX11::_update_real_mouse_position(const WindowData& wd)
{
	Window root_return, child_return;
	int root_x, root_y, win_x, win_y;
	unsigned int mask_return;

	Bool xquerypointer_result = XQueryPointer(x11_display, wd.x11_window, &root_return,
		&child_return, &root_x, &root_y, &win_x, &win_y, &mask_return);

	if (xquerypointer_result) {
		if (win_x > 0 && win_y > 0 && win_x <= wd.size.width && win_y <= wd.size.height) {
			last_mouse_pos.x = win_x;
			last_mouse_pos.y = win_y;
			last_mouse_pos_valid = true;
			Input::set_mouse_position(last_mouse_pos);
		}
	}
}

bool DisplayServerX11::_refresh_device_info()
{
	int event_base, error_base;

	print_verbose("XInput: Refreshing devices.");

	if (!XQueryExtension(x11_display, "XInputExtension", &xi.opcode, &event_base, &error_base)) {
		print_verbose("XInput extension not available. Please upgrade your distribution.");
		return false;
	}

	int xi_major_query = XINPUT_CLIENT_VERSION_MAJOR;
	int xi_minor_query = XINPUT_CLIENT_VERSION_MINOR;

	if (XIQueryVersion(x11_display, &xi_major_query, &xi_minor_query) != Success) {
		print_verbose(vformat(
			"XInput 2 not available (server supports %d.%d).", xi_major_query, xi_minor_query));
		xi.opcode = 0;
		return false;
	}

	if (xi_major_query < XINPUT_CLIENT_VERSION_MAJOR ||
		(xi_major_query == XINPUT_CLIENT_VERSION_MAJOR &&
			xi_minor_query < XINPUT_CLIENT_VERSION_MINOR)) {
		print_verbose(
			vformat("XInput %d.%d not available (server supports %d.%d). Touch input unavailable.",
				XINPUT_CLIENT_VERSION_MAJOR, XINPUT_CLIENT_VERSION_MINOR, xi_major_query,
				xi_minor_query));
	}

	xi.absolute_devices.clear();
	xi.touch_devices.clear();
	xi.pen_inverted_devices.clear();
	xi.last_relative_time = 0;

	int dev_count;
	XIDeviceInfo* info = XIQueryDevice(x11_display, XIAllDevices, &dev_count);

	for (int i = 0; i < dev_count; i++) {
		XIDeviceInfo* dev = &info[i];
		if (!dev->enabled) {
			continue;
		}
		if (!(dev->use == XISlavePointer || dev->use == XIFloatingSlave)) {
			continue;
		}

		bool direct_touch = false;
		bool absolute_mode = false;
		int resolution_x = 0;
		int resolution_y = 0;
		double abs_x_min = 0;
		double abs_x_max = 0;
		double abs_y_min = 0;
		double abs_y_max = 0;
		double pressure_min = 0;
		double pressure_max = 0;
		double tilt_x_min = 0;
		double tilt_x_max = 0;
		double tilt_y_min = 0;
		double tilt_y_max = 0;
		for (int j = 0; j < dev->num_classes; j++) {
#ifdef TOUCH_ENABLED
			if (dev->classes[j]->type == XITouchClass &&
				((XITouchClassInfo*)dev->classes[j])->mode == XIDirectTouch) {
				direct_touch = true;
			}
#endif
			if (dev->classes[j]->type == XIValuatorClass) {
				XIValuatorClassInfo* class_info = (XIValuatorClassInfo*)dev->classes[j];

				if (class_info->number == VALUATOR_ABSX && class_info->mode == XIModeAbsolute) {
					resolution_x = class_info->resolution;
					abs_x_min = class_info->min;
					abs_x_max = class_info->max;
					absolute_mode = true;
				}
				else if (class_info->number == VALUATOR_ABSY &&
						   class_info->mode == XIModeAbsolute) {
					resolution_y = class_info->resolution;
					abs_y_min = class_info->min;
					abs_y_max = class_info->max;
					absolute_mode = true;
				}
				else if (class_info->number == VALUATOR_PRESSURE &&
						   class_info->mode == XIModeAbsolute) {
					pressure_min = class_info->min;
					pressure_max = class_info->max;
				}
				else if (class_info->number == VALUATOR_TILTX &&
						   class_info->mode == XIModeAbsolute) {
					tilt_x_min = class_info->min;
					tilt_x_max = class_info->max;
				}
				else if (class_info->number == VALUATOR_TILTY &&
						   class_info->mode == XIModeAbsolute) {
					tilt_y_min = class_info->min;
					tilt_y_max = class_info->max;
				}
			}
		}
		if (direct_touch) {
			xi.touch_devices.push_back(dev->deviceid);
			print_verbose("XInput: Using touch device: " + String(dev->name));
		}
		if (absolute_mode) {
			// If no resolution was reported, use the min/max ranges.
			if (resolution_x <= 0) {
				resolution_x = (abs_x_max - abs_x_min) * abs_resolution_range_mult;
			}
			if (resolution_y <= 0) {
				resolution_y = (abs_y_max - abs_y_min) * abs_resolution_range_mult;
			}
			xi.absolute_devices[dev->deviceid] =
				Vector2(abs_resolution_mult / resolution_x, abs_resolution_mult / resolution_y);
			print_verbose("XInput: Absolute pointing device: " + String(dev->name));
		}

		xi.pressure = 0;
		xi.pen_pressure_range[dev->deviceid] = Vector2(pressure_min, pressure_max);
		xi.pen_tilt_x_range[dev->deviceid] = Vector2(tilt_x_min, tilt_x_max);
		xi.pen_tilt_y_range[dev->deviceid] = Vector2(tilt_y_min, tilt_y_max);
		xi.pen_inverted_devices[dev->deviceid] = String(dev->name).findn("eraser") > 0;
	}

	XIFreeDeviceInfo(info);
#ifdef TOUCH_ENABLED
	if (!xi.touch_devices.size()) {
		print_verbose("XInput: No touch devices found.");
	}
#endif

	return true;
}

void DisplayServerX11::_flush_mouse_motion()
{
	// Block events polling while flushing motion events.
	MutexLock mutex_lock(events_mutex);

	for (uint32_t event_index = 0; event_index < polled_events.size(); ++event_index) {
		XEvent& event = polled_events[event_index];
		if (XGetEventData(x11_display, &event.xcookie) && event.xcookie.type == GenericEvent &&
			event.xcookie.extension == xi.opcode) {
			XIDeviceEvent* event_data = (XIDeviceEvent*)event.xcookie.data;
			if (event_data->evtype == XI_RawMotion) {
				XFreeEventData(x11_display, &event.xcookie);
				polled_events.remove_at(event_index--);
				continue;
			}
			XFreeEventData(x11_display, &event.xcookie);
			break;
		}
	}

	xi.relative_motion.x = 0;
	xi.relative_motion.y = 0;
}

